function getDetailContentByField(t,n,e,a,s){let d;if("Otros"===n&&"brand"===t){const t=a.getGroupedData().find(t=>"Otros"===t.label);d=t&&t.otherLabels?D.assets.filter(n=>t.otherLabels.includes(n.brand)):[]}else d="status"===t?D.assets.filter(t=>(t.status||"Sin estado")===n):"category"===t?D.assets.filter(t=>(t.category||"Sin categoría")===n):"brand"===t?D.assets.filter(t=>(t.brand||"Sin marca")===n):[];const r="Otros"===n&&"brand"===t,o="pie"===s||"funnel"===s||"pyramid"===s||"hbar"===s;return`\n    <div class="tbl-wrap">\n      <table class="tbl">\n        <thead>\n          <tr>\n            <th>Código</th>\n            <th>Nombre</th>\n            <th>Categoría</th>\n            ${"status"===t?"<th>Tipo</th>":""}\n            <th>Estado</th>\n            ${r?"<th>Marca</th>":""}\n            <th>Responsable</th>\n            ${o?"<th>Valor</th>":""}\n          </tr>\n        </thead>\n        <tbody>\n          ${d.map(n=>`\n            <tr>\n              <td>${esc(n.code||"—")}</td>\n              <td>${esc(n.name)}</td>\n              <td>${esc(n.category||"—")}</td>\n              ${"status"===t?`<td>${esc(n.type||"—")}</td>`:""}\n              <td>${esc(n.status||"—")}</td>\n              ${r?`<td>${esc(n.brand||"—")}</td>`:""}\n              <td>${esc(n.assignedTo||"—")}</td>\n              ${o?`<td>${money(n.cost)}</td>`:""}\n            </tr>\n          `).join("")}\n        </tbody>\n      </table>\n    </div>\n  `}function getMovementsContent(t,n){let e=D.movements.filter(n=>day(n.date)===t);return n.includes("Activos")?e=e.filter(t=>"Activo"===t.kind):n.includes("Insumos")&&(e=e.filter(t=>"Insumo"===t.kind)),`\n    <div class="tbl-wrap">\n      <table class="tbl">\n        <thead>\n          <tr>\n            <th>Tipo</th>\n            <th>Acción</th>\n            <th>Responsable</th>\n            <th>Destino</th>\n            <th>Cantidad</th>\n          </tr>\n        </thead>\n        <tbody>\n          ${e.map(t=>`\n            <tr>\n              <td>${esc(t.kind)}</td>\n              <td>${esc(t.action)}</td>\n              <td>${esc(t.person||"—")}</td>\n              <td>${esc(t.destination||"—")}</td>\n              <td>${t.quantity}</td>\n            </tr>\n          `).join("")}\n        </tbody>\n      </table>\n    </div>\n  `}function getPurchasesContent(t,n){const e=["ene","feb","mar","abr","may","jun","jul","ago","sep","oct","nov","dic"].indexOf(t.toLowerCase());if(-1===e)return"";const a=`${(new Date).getFullYear()}-${String(e+1).padStart(2,"0")}`;let s=D.purchases.filter(t=>day(t.date).slice(0,7)===a);return n.includes("Activos")?s=s.filter(t=>"Activo"===t.type):n.includes("Insumos")&&(s=s.filter(t=>"Insumo"===t.type)),`\n    <div class="tbl-wrap">\n      <table class="tbl">\n        <thead>\n          <tr>\n            <th>Fecha</th>\n            <th>Tipo</th>\n            <th>Proveedor</th>\n            <th>Marca</th>\n            <th>Total</th>\n          </tr>\n        </thead>\n        <tbody>\n          ${s.map(t=>`\n            <tr>\n              <td>${day(t.date)}</td>\n              <td>${esc(t.type)}</td>\n              <td>${esc(t.supplier||"—")}</td>\n              <td>${esc(t.brand||"—")}</td>\n              <td>${money(t.total)}</td>\n            </tr>\n          `).join("")}\n        </tbody>\n      </table>\n    </div>\n  `}